# name: triplet_variety_choice_rate
# description: Among trials where the sequences differ in the number of distinct length-3 substrings, the fraction choosing the sequence with more distinct triplets (pattern variety / complexity); observed > null means people value subpattern diversity beyond what balance and alternation capture.
def test_statistic(df):
    def variety(s):
        if len(s) < 3:
            return 0
        return len({s[i:i + 3] for i in range(len(s) - 2)})
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: variety(s) for s in u}
    va = df["sequence_a"].map(m).to_numpy()
    vb = df["sequence_b"].map(m).to_numpy()
    y = df["chose_left"].to_numpy()
    mask = va != vb
    if mask.sum() == 0:
        return 0.5
    chose_more = np.where(va > vb, y, 1 - y)
    return float(chose_more[mask].mean())

# name: perfect_alternation_choice_rate
# description: On trials where exactly one sequence perfectly alternates (HTHT...), the fraction choosing that perfectly alternating sequence; observed < null means people reject the strict alternating pattern more than the model's periodicity penalty predicts, observed > null means less.
def test_statistic(df):
    def perfalt(s):
        return float(len(s) > 2 and all(s[i] != s[i - 1] for i in range(1, len(s))))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: perfalt(s) for s in u}
    a = df["sequence_a"].map(m).to_numpy()
    b = df["sequence_b"].map(m).to_numpy()
    y = df["chose_left"].to_numpy()
    mask = (a + b) == 1
    if mask.sum() == 0:
        return 0.5
    chose_alt = np.where(a == 1, y, 1 - y)
    return float(chose_alt[mask].mean())

# name: shorter_longest_run_choice_rate
# description: Among trials whose two sequences differ in longest-run length by >=2, the fraction of choices of the sequence with the shorter longest run; observed > null means people penalise long streaks more than the model's balance/alternation features predict.
def test_statistic(df):
    def maxrun(s):
        best = cur = 1
        for i in range(1, len(s)):
            cur = cur + 1 if s[i] == s[i - 1] else 1
            best = max(best, cur)
        return best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: maxrun(s) for s in u}
    ra = df["sequence_a"].map(m).to_numpy()
    rb = df["sequence_b"].map(m).to_numpy()
    y = df["chose_left"].to_numpy()
    mask = np.abs(ra - rb) >= 2
    if mask.sum() == 0:
        return 0.5
    chose_shorter = np.where(ra < rb, y, 1 - y)
    return float(chose_shorter[mask].mean())

# name: participant_sd_left_rate
# description: Standard deviation across participants of their overall chose_left rate; observed > null means participants carry individual side biases/response styles that the model's single shared side_bias underproduces.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().std(ddof=0))
